#!/usr/bin/env python3
"""Add CD-1min to the 11-system full-coverage multiverse.

This script keeps the original 778 scoring-unit universe used by
multiverse_pair_analysis.py, then adds CD-1min rows from two sources:

* OpenRCA: existing unified input files already contain method="cd1min".
* RCAEval/PetShop: fresh cross-benchmark CD-1min adapter output generated by
  smoke_cd_causal_adapters.py on the 3090 host, where RCAEval RE1 symlinks are
  resolvable.

Outputs mirror the existing full-coverage multiverse directory, but with four
methods: BARO, max-|Z|, alert-count, and CD-1min.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

import pandas as pd

import multiverse_pair_analysis as mp


DEFAULT_REPO_ROOT = Path("$HOME/mnt/3090/auditstack")
DEFAULT_UNIFIED_INPUTS = DEFAULT_REPO_ROOT / "results_xbench_11sys_unified" / "_inputs"
DEFAULT_ALERT_INPUTS = DEFAULT_REPO_ROOT / "results_xbench_11sys_alertcount" / "_inputs"
DEFAULT_CD1MIN_PER_CASE = DEFAULT_REPO_ROOT / "results_stats" / "cd1min_adapt_main_11sys" / "per_case.csv"
DEFAULT_OUTPUT_DIR = DEFAULT_REPO_ROOT / "results_stats" / "multiverse_cd1min_main"

METHODS = ["baro", "z_family", "alertcount", "cd1min"]
DISPLAY_NAMES = {
    "baro": "BARO",
    "z_family": "max-|Z|",
    "alertcount": "alert-count",
    "cd1min": "CD-1min",
}

RCAEVAL_SYSTEM_MAP = {
    "online-boutique": "OB",
    "sock-shop-2": "SS",
    "train-ticket": "TT",
}


def write_json(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2, default=float)


def openrca_cd1min_from_unified(unified: pd.DataFrame) -> pd.DataFrame:
    cols = ["benchmark", "system", "system_id", "case", "q_idx", "case_id", "method", "correct"]
    out = unified[
        (unified["benchmark"] == "openrca")
        & (unified["method"] == "cd1min")
    ][cols].copy()
    return out


def adapted_cd1min_from_per_case(path: Path) -> pd.DataFrame:
    df = pd.read_csv(path)
    rows = []
    for row in df.to_dict("records"):
        family = row["family"]
        raw_system = row["system"]
        if family == "rcaeval":
            benchmark = "rcaeval"
            system = RCAEVAL_SYSTEM_MAP[raw_system]
            correct_col = "acc@1"
        elif family == "petshop":
            benchmark = "petshop"
            system = raw_system
            correct_col = "acc@1"
        else:
            continue

        system_id = f"{benchmark}::{system}"
        case = str(row["case"])
        q_idx = 0
        rows.append({
            "benchmark": benchmark,
            "system": system,
            "system_id": system_id,
            "case": case,
            "q_idx": q_idx,
            "case_id": f"{system_id}|{case}#{q_idx}",
            "method": "cd1min",
            "correct": float(row[correct_col]),
        })
    return pd.DataFrame(rows)


def build_cd1min_multiverse(
    unified: pd.DataFrame,
    alert: pd.DataFrame,
    cd1min_per_case: Path,
) -> tuple[pd.DataFrame, dict]:
    base3, base_sanity = mp.build_full_coverage_long(unified, alert)

    cd_openrca = openrca_cd1min_from_unified(unified)
    cd_adapted = adapted_cd1min_from_per_case(cd1min_per_case)
    cd_all = pd.concat([cd_openrca, cd_adapted], ignore_index=True)

    combined = pd.concat([base3, cd_all], ignore_index=True)
    wide = combined.pivot_table(
        index=["benchmark", "system", "system_id", "case", "q_idx", "case_id"],
        columns="method",
        values="correct",
        aggfunc="mean",
    ).reset_index()
    complete = wide.dropna(subset=METHODS).copy()
    full = complete.melt(
        id_vars=["benchmark", "system", "system_id", "case", "q_idx", "case_id"],
        value_vars=METHODS,
        var_name="method",
        value_name="correct",
    )

    coverage = (
        combined.groupby(["system_id", "method"])["case_id"]
        .nunique()
        .unstack(fill_value=0)
        .astype(int)
        .sort_index()
    )
    complete_by_system = complete.groupby("system_id").size().to_dict()
    sanity = {
        **base_sanity,
        "methods": METHODS,
        "display_names": DISPLAY_NAMES,
        "cd1min_per_case": str(cd1min_per_case),
        "cd1min_rows_openrca": int(len(cd_openrca)),
        "cd1min_rows_adapted": int(len(cd_adapted)),
        "n_complete_scoring_units_4method": int(len(complete)),
        "n_long_rows_4method": int(len(full)),
        "n_systems_4method": int(complete["system_id"].nunique()),
        "complete_units_by_system_4method": complete_by_system,
        "method_coverage_before_intersection": coverage.to_dict(),
    }
    return full.sort_values(["system_id", "case_id", "method"]).reset_index(drop=True), sanity


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--unified-inputs", type=Path, default=DEFAULT_UNIFIED_INPUTS)
    ap.add_argument("--alert-inputs", type=Path, default=DEFAULT_ALERT_INPUTS)
    ap.add_argument("--cd1min-per-case", type=Path, default=DEFAULT_CD1MIN_PER_CASE)
    ap.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIR)
    ap.add_argument("--bootstrap-n-iter", type=int, default=5000)
    ap.add_argument("--seed", type=int, default=42)
    args = ap.parse_args()

    args.output_dir.mkdir(parents=True, exist_ok=True)
    unified = mp.load_with_inputs_dir(args.unified_inputs)
    alert = mp.load_with_inputs_dir(args.alert_inputs)

    full, sanity = build_cd1min_multiverse(unified, alert, args.cd1min_per_case)
    sanity["unified_inputs"] = str(args.unified_inputs)
    sanity["alert_inputs"] = str(args.alert_inputs)
    sanity["seed"] = args.seed
    sanity["bootstrap_n_iter"] = args.bootstrap_n_iter

    if sanity["baro_alignment_missing_or_extra"] != 0:
        raise RuntimeError(f"BARO case-id mismatch between blocks: {sanity}")
    if sanity["baro_alignment_max_abs_diff"] != 0.0:
        raise RuntimeError(f"BARO score mismatch between blocks: {sanity}")
    if sanity["n_complete_scoring_units_4method"] != 778:
        raise RuntimeError(
            f"Expected 778 complete 4-method scoring units, "
            f"got {sanity['n_complete_scoring_units_4method']}"
        )
    if sanity["n_systems_4method"] != 11:
        raise RuntimeError(f"Expected 11 systems, got {sanity['n_systems_4method']}")

    write_json(args.output_dir / "input_sanity.json", sanity)
    full.to_csv(args.output_dir / "full_coverage_cd1min_long.csv", index=False)
    mp.method_coverage(full).to_csv(args.output_dir / "method_coverage.csv", index=False)

    original_methods = mp.FULL_METHODS
    original_display = mp.DISPLAY_NAMES
    mp.FULL_METHODS = METHODS
    mp.DISPLAY_NAMES = DISPLAY_NAMES
    try:
        per_system, pair_summary = mp.compute_pair_deltas(full, args.bootstrap_n_iter, args.seed)
        loso_summary, loso_per_system = mp.compute_loso(full, args.bootstrap_n_iter, args.seed)
    finally:
        mp.FULL_METHODS = original_methods
        mp.DISPLAY_NAMES = original_display

    per_system.to_csv(args.output_dir / "per_system_deltas.csv", index=False)
    pair_summary.to_csv(args.output_dir / "pair_summary.csv", index=False)
    loso_summary.to_csv(args.output_dir / "loso_pair_summary.csv", index=False)
    loso_per_system.to_csv(args.output_dir / "loso_pair_per_system.csv", index=False)
    per_system.pivot(index="pair", columns="system", values="delta_pp").reset_index().to_csv(
        args.output_dir / "multiverse_delta_matrix.csv",
        index=False,
    )

    print(f"[written] {args.output_dir}")
    print(pair_summary.to_string(index=False))
    print(loso_summary.to_string(index=False))


if __name__ == "__main__":
    main()
